const {vec, smat} = NMath;
const {vertices} = await IO.loadMesh("/assets/bunny.obj");

let pts = vertices.map(vertex => vec(...vertex));
const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    const scaled = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};
pts = normalizeVectors(pts);

const k = 8;
const graph = Graph.knn(pts, k, (x, y) => x.sub(y).length());
const normalLength = 0.05;
const n = pts.length;

// the normal is the eigenvector with the lowest eigenvalue of the neighborhood covariance
const estimateNormal = id => {
    const neighborhood = [id, ...graph.getNeighbors(id)].map(j => graph.getVertex(j).vertex.toArray());
    const {components} = PCA.new(neighborhood, 3);
    return components[components.length - 1];
};

const normals = pts.map((_, i) => estimateNormal(i));
const neighbors = pts.map((_, i) => graph.getNeighbors(i).map(Number));

// mean of n_i . n_j over the neighbors: 1 is consistent, -1 is flipped w.r.t. neighbors
const orientationScores = field => field.map((normal, i) =>
    neighbors[i].reduce((sum, j) => sum + normal.dot(field[j]), 0) / Math.max(1, neighbors[i].length)
);

// angular synchronization: the leading eigenvector of W_ij = n_i . n_j gives the sign of each normal
const synchronize = field => {
    // the shift makes the matrix positive semidefinite, so the power method finds the largest eigenvalue
    const shift = Math.max(...neighbors.map(list => list.length));
    const builder = smat.builder(n, n);
    for (let i = 0; i < n; i++) {
        builder.set(i, i, shift);
        neighbors[i].forEach(j => builder.set(i, j, field[i].dot(field[j])));
    }
    const {eigenvectors} = builder.build().eigen({k: 1, maxIterations: 2000, tolerance: 1e-4});
    const signs = eigenvectors[0].toArray().map(x => (x < 0 ? -1 : 1));
    const flipped = field.map((normal, i) => normal.scale(signs[i]));
    // the global sign is free, so make most normals point away from the center of the cloud
    const outward = flipped.reduce((sum, normal, i) => sum + normal.dot(pts[i]), 0);
    return outward < 0 ? flipped.map(normal => normal.scale(-1)) : flipped;
};

const oriented = synchronize(normals);

const toLines = field => pts.map((p, i) => [p.toArray(), p.add(field[i].scale(normalLength)).toArray()]);
// green: consistent with neighbors, red: inconsistent
const toColors = field => orientationScores(field).map(s => {
    const t = (Math.max(-1, Math.min(1, s)) + 1) / 2;
    return [1 - t, t, 0];
});
const countInconsistent = field => orientationScores(field).filter(s => s < 0).length;
console.log(`inconsistent normals before: ${countInconsistent(normals)} / ${n}`);
console.log(`inconsistent normals after: ${countInconsistent(oriented)} / ${n}`);

const beforePlot = IO.plotLineCloud(toLines(normals), {color: toColors(normals)});
const afterPlot = IO.plotLineCloud(toLines(oriented), {color: toColors(oriented)});

const ui = IO.UI(
    {type: "group", value: () => [
        {type: "canvas", value: () => beforePlot},
        {type: "canvas", value: () => afterPlot},
    ]},
);
ui;
